<script setup lang="ts">
import { ref } from 'vue'
import { currentOffice, supportState, selectOffice, switchPersona, resetSupportDemo } from '@/services/supportDemo'
import AppModal from './AppModal.vue'
const error=ref('');const reset=ref(false)
function change(action:()=>void){try{action();error.value=''}catch(e){error.value=(e as Error).message}}
</script>
<template><div class="module-context"><span class="demo-pill">M01 + M02 · DÉMO</span><label>Officine de démonstration<select :value="currentOffice.id" @change="change(()=>selectOffice(($event.target as HTMLSelectElement).value))"><option v-for="o in supportState.offices" :key="o.id" :value="o.id">{{o.name}}</option></select></label><label>Point de vue simulé<select :value="supportState.persona" @change="change(()=>switchPersona(($event.target as HTMLSelectElement).value as 'office'|'company'))"><option value="office">Administrateur officine</option><option value="company">Coordination entreprise</option></select></label><button class="text-link" @click="reset=true">Restaurer les exemples</button><p v-if="error" role="alert">{{error}}</p></div><p class="module-disclaimer">Simulation locale des modules 01 & 02 · changer de vue ne constitue pas une autorisation réelle. Aucun email envoyé, aucune certification ABMed.</p><AppModal v-model="reset" title="Restaurer les exemples des modules 01 & 02 ?" size="small"><div class="form-body"><p>Les officines, accompagnateurs, demandes et missions fictifs seront restaurés. Les actions qualité et l’équipe de l’ancienne démo ne seront pas modifiées.</p></div><template #footer><button class="button secondary" @click="reset=false">Annuler</button><button class="button primary" @click="change(resetSupportDemo);reset=false">Restaurer</button></template></AppModal></template>
